cat > bot.mjs <<'EOF'
import fs from "node:fs";

// Suppression gate. State: one atomic file per (event type, address) in STATE_DIR.
// Marketing: blocked by unsubscribe, spam complaint or hard bounce.
// Transactional: blocked only by hard bounce (address does not exist). An unsubscribe
// or complaint about marketing mail does not stop receipts or password resets.

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

// Returns { exact, base } or null. exact keeps a +tag; base drops it. Gmail dots are ignored.
function canon(raw) {
  if (typeof raw !== "string") return null;
  let s = raw.normalize("NFKC").trim();
  const angle = s.match(/<([^<>]*)>\s*$/);
  if (angle) s = angle[1].trim();
  s = s.replace(/^mailto:/i, "").trim().replace(/^<|>$/g, "").trim();
  if ((s.match(/@/g) || []).length !== 1 || /[\s,;<>()"]/.test(s)) return null;
  let [local, domain] = s.split("@");
  domain = domain.toLowerCase().replace(/\.+$/, "");
  local = local.toLowerCase();
  if (!local || !domain || !domain.includes(".")) return null;
  if (domain === "googlemail.com") domain = "gmail.com";
  const gmail = domain === "gmail.com";
  const plus = local.indexOf("+");
  let base = plus > 0 ? local.slice(0, plus) : local;
  let exact = local;
  if (gmail) {
    base = base.replace(/\./g, "");
    exact = exact.replace(/\./g, "");
  }
  return { exact: `${exact}@${domain}`, base: `${base}@${domain}` };
}

const TYPES = new Set(["unsubscribe", "spam_complaint", "hard_bounce"]);

export async function recordEvent({ email, type, now } = {}) {
  if (!TYPES.has(type)) throw new Error(`unknown event type: ${type}`);
  const c = canon(email);
  if (!c) throw new Error(`invalid email address: ${email}`);
  const dir = stateDir();
  const at = now instanceof Date && !isNaN(now) ? now.toISOString() : null;
  const rec = { type, email: c.exact, at };
  gkWrite(dir, `${type}:${c.exact}`, rec);
  // Unsubscribe and complaint cover every +tag alias of the mailbox; a bounce is exact only.
  if (type !== "hard_bounce") gkWrite(dir, `${type}:${c.base}`, rec);
  return { recorded: true };
}

export async function checkEmail({ email, kind, now } = {}) {
  if (kind !== "marketing" && kind !== "transactional") return { allowed: false, rule: "unknown-kind" };
  const c = canon(email);
  if (!c) return { allowed: false, rule: "invalid-address" };
  let dir;
  try {
    dir = stateDir();
    const has = (type, key) => gkRead(dir, `${type}:${key}`) !== null;
    if (has("hard_bounce", c.exact)) return { allowed: false, rule: "hard-bounce" };
    if (kind === "marketing") {
      if (has("unsubscribe", c.exact) || has("unsubscribe", c.base)) return { allowed: false, rule: "unsubscribed" };
      if (has("spam_complaint", c.exact) || has("spam_complaint", c.base)) return { allowed: false, rule: "spam-complaint" };
    }
  } catch {
    return { allowed: false, rule: "state-unreadable" };
  }
  return { allowed: true, rule: "" };
}
